INSERT INTO `list33` (`id`, `domain`, `id_user`, `premium`, `page`, `status`, `time`, `timeupdate`, `statuschange`, `price`, `geo`, `name`, `f1563581500n`, `f1563582562n`) VALUES
(1,	'1v1-crm.ru',	17,	0,	'',	1,	1563582424,	0,	0,	0,	'',	'Приветствие',	'Здравствуйте, ​|ФИО|. Меня зовут ​|имя оператора|.  Это интернет ­ магазин |Название|. Вы оставили заявку на нашем сайте. Все верно?',	'14'),
(2,	'1v1-crm.ru',	17,	0,	'',	1,	1563583716,	0,	0,	0,	'',	'Клиент  подтверждает заказ',	'Замечательно, давайте я вам немного расскажу о том, как применять наш продукт. Наш продукт – это комплекс компонентов. Снижение веса происходит за счет нормализации естественных процессов обмена веществ организма, что дает длительный эффект и предотвращает повторный набор веса.  Очень важно не пропускать и принимать продукт регулярно.  Принимать нужно один-два раза в день, каждый день.',	'17'),
(3,	'1v1-crm.ru',	17,	0,	'',	1,	1563583743,	0,	0,	0,	'',	'Окончание разговора',	'Итак, ваше ФИО ­ \nВаш адрес ­  \nСумма заказа ­ \nОтложите пожалуйста нужную сумму заранее и будьте на связи, чтобы мы оперативно оповещали вас. Скоро созвонимся с вами!',	'3');
