INSERT INTO `list5` (`id`, `domain`, `id_user`, `premium`, `page`, `status`, `time`, `timeupdate`, `statuschange`, `price`, `geo`, `name`, `f1557931993n`, `f1557932014n`, `f1557932035n`) VALUES
(1,	'1v1-crm.ru',	17,	0,	'',	1,	1558041674,	1558041674,	0,	0,	'',	'НДЗ',	'Здравствуйте, наш менеджер с телефона +74953744725 звонил вам для подтверждения заказа товара. Мы снова вам перезвоним в течении 2 часов.',	'sendertest',	'ОКК'),
(2,	'1v1-crm.ru',	17,	0,	'',	1,	1560214870,	1560529181,	0,	0,	'',	'ОКК',	'Здравствуйте, если у вас есть вопросы по качеству продукции или срокам доставки напишите нам письмо на sluzhba-podderzhki.19@mail.ru мы отреагируем и постараемся решить вопрос максимально быстро!',	'sendertest',	''),
(3,	'1v1-crm.ru',	17,	0,	'',	1,	1565425098,	0,	0,	0,	'',	'Переданы на склад',	'Здравствуйте {{fio}}! Ваш заказ и подарок приняты на доставку. Срок прибытия 3-10 дней. Ожидайте СМС с номером заказа!',	'sendertest',	''),
(4,	'1v1-crm.ru',	17,	0,	'',	1,	1565425120,	0,	0,	0,	'',	'День 6',	'Уважаемый клиент, ваша посылка хранится в отделении почты уже 6 дней. Убедительно просим вас выкупить ее в ближайшее время, так как в противном случае ваш заказ будет передан в юридический отдел.',	'sendertest',	''),
(5,	'1v1-crm.ru',	17,	0,	'',	1,	1565425144,	0,	0,	0,	'',	'День 7',	'Уважаемый клиент, ваша посылка хранится на почте уже 7 дней . Вам необходимо забрать ваш заказ {{russianpostTrack}} из интернет магазина в вашем отделении почты в течении 2 дней. В противном случае http://общество-защиты-прав.рф подготовит иск в суд на основании ст. 432,436 ГК РФ. Вы будете обязаны компенсировать полную сумму заказа с учетом доставки включая судебные расходы в размере 12 307 рублей (1837 - расходы компании, 470 - гос. пошлина, 10 000 - yслуга представителя). Заключение договора Оферты и Ваше согласие со всеми условиями подтверждает запись телефонных разговоров. Во избежании данной ситуации, настоятельно рекомендуем выкупить, сделанный лично Вами заказ.',	'sendertest',	''),
(6,	'1v1-crm.ru',	17,	0,	'',	1,	1565425185,	0,	0,	0,	'',	'День 9',	'Здравствуйте {{fio}}! Юр. Отделом интернет магазина на вас подано исковое заявление. Дополнительно к сумме вашего заказа идет сумма 12 307₽, дело будет рассмотрено в Замоскворецком районном суде через 6 дней по адресу г. Москва, ул. Татарская, д.1. В случае выкупа заказа в течении 5 дней, юр. отдел отзовет исковое заявление. Возможен обмен / возврат товара в течении 14 дней.',	'sendertest',	''),
(7,	'1v1-crm.ru',	17,	0,	'',	1,	1565425211,	0,	0,	0,	'',	'День 11',	'Здравствуйте, {{fio}}! По закону мы обязаны сообщить, что через 4 дня иск по ст. 432,436 ГК РФ будет рассмотрен в суде по адресу г. Москва, ул. Татарская, д.1. В случае выкупа товара в течение 4 дней иск будет отозван',	'sendertest',	''),
(8,	'1v1-crm.ru',	17,	0,	'',	1,	1565425232,	0,	0,	0,	'',	'День 13',	'Здравствуйте, {{fio}}! Через 2 дня иск по ст. 432,436 ГК РФ будет рассмотрен в суде по адресу г. Москва, ул. Татарская, д.1. В случае выкупа товара в течение 2 дней иск будет отозван.',	'sendertest',	''),
