INSERT INTO `list_table` (`id`, `domain`, `domain_id`, `title`, `email`, `mod_menu`, `position`, `published`, `moderation`, `sf`, `ts`, `count`, `html1`, `html2`, `html3`, `html4`, `html5`, `html6`, `html7`, `html8`, `html9`, `html10`) VALUES
(1,	'1v1-crm.ru',	1,	'Шаблоны для робота',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'\r\n',	'',	'',	'',	'<div class=\"frm\">\n	<h3><span>Голосовой шаблон {{{ids}}}</span></h3>\n    <span class=\"label\">Название шаблона<i required>*</i></span>{{{name.input[type:text,class:w500,placeholder:Название]}}}<br/>\n    <span class=\"label\">Голос<i required>*</i></span>{{{f1557930211n.select}}}<br/>\n    <span class=\"label\">Тема сообщения<i required>*</i></span>{{{f1557930402n.input[type:text,class:w500,placeholder:Тема сообщения]}}}<br/>\n    <span class=\"label\">Отправлять от<i required>*</i></span>{{{f1557930422n.input[type:text,class:w500,placeholder:Номер который будет отображен клиенту (АОН)]}}}<br/>\n    <span class=\"label\">Текст сообщения<i required>*</i></span>{{{f1557930441n.textarea}}}\n<div class=\"frmmar\"></div>\n	<button class=\"save\" action=\"addf\">Продолжить</button>\n	<span class=\"closeform\">Отмена</span>\n<div class=\"frmmar\"></div>\n<div class=\"alert alert-info guide-voice\">\n    В шаблоне текста SMS можно использовать следующие теги:\n    <ul>\n        <li><code>{{id}}</code> - возвращает номер заказа пользователя</li>\n        <li><code>{{status}}</code> - текущий статус заказа</li>\n        <li><code>{{date}}</code> - дата заказа в формате: 15.05.2019</li>\n        <li><code>{{time}}</code> - время заказа в формате: 16:51</li>\n        <li><code>{{datetime}}</code> - дата и время в формате: 2019-05-15 16:51:54</li>\n        <li><code>{{lastUpdate}}</code> - статус изменен в формате: 2019-05-15 16:51:54</li>\n        <li><code>{{lastModify}}</code> - последние изменение в формате: 2019-05-15 16:51:54</li>\n        <li><code>{{approvedAt}}</code> - дата и время апрува в формате: 2019-05-15 16:51:54, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{shippedAt}}</code> - дата и время отправки в формате: 2019-05-15 16:51:54, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{canceledAt}}</code> - дата и время отмены в формате: 2019-05-15 16:51:54, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{buyoutAt}}</code> - дата и время выкупа в формате: 2019-05-15 16:51:54, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{refundedAt}}</code> - дата и время возврата в формате: 2019-05-15 16:51:54, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{price}}</code> - цена товара</li>\n        <li><code>{{total}}</code> - сумма заказа</li>\n        <li><code>{{goods_names}}</code> - наименование товаров через запятую</li>\n        <li><code>{{russianpostTrack}}</code> - номер отправления Почты России</li>\n        <li><code>{{russianpostTrackingIndex}}</code> - индекс почтового отделения последнего статуса отслеживания</li>\n        <li class=\"rp-tags\"><code>{{russianpostOfficeAddress}}</code> - адрес почтового отделения</li>\n        <li class=\"rp-tags\"><code>{{russianpostOfficePhone}}</code> - телефон почтового отделения</li>\n        <li class=\"rp-tags\"><code>{{russianpostWorkTimeToday}}</code> - режим работы почтового отделения сегодня</li>\n        <li class=\"rp-tags\"><code>{{russianpostWorkTimeTomorrow}}</code> - режим работы почтового отделения завтра</li>\n        <li><code>{{key_1=\"@\"}}</code> - переводит клиента на оператора при звонке робота</li>\n        <li><code>{{key_2=\"текст\"}}</code> - текст, который клиент услышит после нажатия клавиши <code>2</code></li>\n        <li><code>{{audio=\"http://files.lvcdn.ru/example.mp3\"}}</code> - тег для вставки аудиозаписи</li>\n        <li><code>{{repeat}}</code> - повторить голосовое сообщение еще раз, если нажата клавиша <code>*</code></li>\n        <li><code>{{autoPredictive}}</code> - автоматическое соединение с оператором</li>\n        <li><code>{{domain}}</code> - домен, на котором пользователь совершил заказ</li>\n        <li><code>{{utm_source}}</code> - метка utm_source</li>\n        <li><code>{{utm_medium}}</code> - метка utm_medium</li>\n        <li><code>{{utm_campaign}}</code> - метка utm_campaign</li>\n        <li><code>{{utm_content}}</code> - метка utm_content</li>\n        <li><code>{{utm_term}}</code> - метка utm_term</li>\n        <li><code>{{fio}}</code> - возвращает значение поля «Ф.И.О». Аналогичным образом можно использовать поля:\n          <code title=\"Индекс\">{{postIndex}}</code>\n          <code title=\"Регион\">{{region}}</code> \n          <code title=\"Город\">{{city}}</code>\n          <code title=\"Адрес\">{{address}}</code> \n          <code title=\"Телефон\">{{phone}}</code>\n          <code title=\"Кол-во\">{{quantity}}</code> \n          <code title=\"Комментарий\">{{comment}}</code>\n          <code title=\"Liveinform\">{{additional1}}</code> \n          <code title=\"Размер\">{{additional2}}</code>\n          <code title=\"Дожим\">{{additional11}}</code> \n          <code title=\"Масса\">{{additional14}}</code>\n      	</li>\n    </ul>\n</div>\n</div>\n',	'<div class=\"request\">\n    <span>{{{name}}}</span><span>{{{f1557930211n}}} голос</span><span>{{{f1557930422n}}}</span><span>{{{f1557930402n}}}</span><span>{{{f1557930441n}}}</span>\n    <details class=\"owner owner2\">\n        <summary class=\"tosetting\"></summary>\n        <div> <a crm=\"edit\" list=\"1\" class=\"add owner\">Редактировать</a>\n            <a crm=\"remove\" list=\"1\" class=\"delete owner\">В архив</a>\n        </div>\n    </details>\n</div>'),
(2,	'1v1-crm.ru',	2,	'Правила робо-прозвона',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'<div class=\"frm\">\n	<h3><span>Правило робо-прозвона {{{ids}}}</span></h3>\n    <span class=\"label\">Название<i required>*</i></span>{{{name.input[type:text,class:w500,placeholder:Название]}}}<br/>\n    <span class=\"label\">Шаблон</span>{{{robot_template.select[class:w500]}}}\n<div class=\"frmmar\"></div>\n  	<h3>Если</h3>\n    <span class=\"label\">Статус голосового SMS</span>{{{voiceSmsStatus.multiselect[class:w500]}}}<br/>\n    <span class=\"label\">И поле заказа</span>{{{orderField.select}}}{{{orderSignCompare.radio}}}{{{orderValue.input[type:text,class:w170,placeholder:Значение поля]}}}<br/>\n    <span class=\"label\">И заказ содержит товары</span>{{{goods.multiselect[class:w500]}}}\n<div class=\"frmmar\"></div>\n  	<h3>Тогда</h3>\n    <span class=\"label\">{{{changeStatusCheck.checkbox[label: Изменить статус]}}}</span>{{{changeStatusSelect.select[class:w500]}}}<br/>\n    <span class=\"label\">{{{sendTextSmsCheck.checkbox[label: Отправить текстовое смс]}}}</span>{{{sendTextSmsSelect.select[class:w500]}}}\n    <div class=\"label2\">\n      	<span class=\"label\">{{{recall.checkbox[label: Перезвонить]}}}</span><br/>\n    	Через {{{recallTime.input[type:text,class:w100]}}} минут с шаблоном {{{recallTemplateID.select[class:w500]}}}<br/>\n      	<span>{{{limitTime.checkbox[label: Ограничить перезвоны по времени]}}}</span> с {{{limitTimeOn.input[type:text,class:w100]}}} до {{{limitTimeOff.input[type:text,class:w100]}}}<br/>\n      	Сколько раз нужно перезвонить на 1 заказ {{{limitRecallCount.input[type:text,class:w100]}}} и далее переместить в статус {{{limitRecallStatus.select}}}\n    </div>\n    <div class=\"label2\">\n      	<span class=\"label\">{{{stopStatus.checkbox[label: Остановить правило если заказ находится]}}}</span><br/>\n    	{{{stopStatusRadio.radio}}}{{{stopStatusSelect.multiselect[class:w500]}}}\n    </div>\n    {{{log.checkbox[label: Записывать лог в комментарий заказа после сделанной попытки]}}}\n<div class=\"frmmar\"></div>\n	<button class=\"save\" action=\"addf\">Продолжить</button>\n	<span class=\"closeform\">Отмена</span>\n</div>\n',	'<div class=\"request request2\">\n	<h3>{{{name}}}</h3>\n	<div>\n      \n      \n      \n		<h2>Если по шаблону {{{robot_template}}} статус доставки {{{voiceSmsStatus}}}</h2><hr/>\n		<h2>Тогда \n			<li>{{{changeStatusCheck}}} изменить статус на {{{changeStatusSelect}}}</li>\n			<li>{{{sendTextSmsCheck}}} отправить текстовое смс с шаблоном {{{sendTextSmsSelect}}}</li>\n			<li>{{{recall}}} перезвонить через {{{recallTime}}} минут с шаблоном {{{recallTemplateID}}} (ограничение по времени с {{{limitTimeOn}}} до {{{limitTimeOff}}})<br/>\n          		Сделать {{{limitRecallCount}}} попыток прозвона.\n          	</li>      	\n      	</h2>\n		<p>Правило сработает только в: {{{stopStatusSelect}}}</p>\n  	</div>\n    <details class=\"owner owner2\">\n        <summary class=\"tosetting\"></summary>\n        <div> <a crm=\"edit\" list=\"2\" class=\"add owner\">Редактировать</a>\n            <a crm=\"remove\" list=\"2\" class=\"delete owner\">В архив</a>\n        </div>\n    </details>\n</div>'),
(3,	'1v1-crm.ru',	3,	'История звонков робо-прозвона',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'',	'<div class=\"request\">\n    <span>{{{f1557933212n}}}</span><span>{{{f1557933227n}}}</span><span>{{{f1557933240n}}}</span>\n    <span>{{{f1557933250n}}}</span><span>{{{f1557933260n}}}</span><span>{{{f1557933271n}}}</span>\n    <span>{{{f1557933283n}}}</span><span>{{{f1557933295n}}}</span><span>{{{f1557933308n}}}</span>\n    <span>{{{f1557933319n}}}</span><span>{{{f1557933337n}}}</span><span>{{{f1557933348n}}}}</span>\n    <details class=\"owner owner2\">\n        <summary class=\"tosetting\"></summary>\n        <div> <a crm=\"edit\" list=\"3\" class=\"add owner\">Редактировать</a>\n            <a crm=\"remove\" list=\"3\" class=\"delete owner\">В архив</a>\n        </div>\n    </details>\n</div>'),
(4,	'1v1-crm.ru',	4,	'История голосовых',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'',	'<div class=\"request\">\n    <span>{{{f1557933635n}}}</span><span>{{{f1557933658n}}}</span><span>{{{f1557933674n}}}</span>\n    <span>{{{f1557933684n}}}</span><span>{{{f1557933695n}}}</span><span>{{{f1557933706n}}}</span>\n    <details class=\"owner owner2\">\n        <summary class=\"tosetting\"></summary>\n        <div> <a crm=\"edit\" list=\"4\" class=\"add owner\">Редактировать</a>\n            <a crm=\"remove\" list=\"4\" class=\"delete owner\">В архив</a>\n        </div>\n    </details>\n</div>'),
(5,	'1v1-crm.ru',	5,	'Шаблоны SMS',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'\r\n',	'',	'',	'',	'<div class=\"frm\">\n	<h3><span>SMS-шаблон {{{ids}}}</span></h3>\n    <span class=\"label\">Тема сообщения<i required>*</i></span>{{{name.input[type:text,class:w500,placeholder:Тема сообщения]}}}<br/>\n    <span class=\"label\">Отправлять от<i required>*</i></span>{{{f1557932014n.input[type:text,class:w500,placeholder:Номер который будет отображен клиенту (АОН)]}}}<br/>\n    <span class=\"label\">Текст сообщения<i required>*</i></span>{{{f1557931993n.textarea}}}\n<div class=\"frmmar\"></div>\n	<button class=\"save\" action=\"addf\">Продолжить</button>\n	<span class=\"closeform\">Отмена</span>\n<div class=\"frmmar\"></div>\n<div class=\"alert alert-info\">\n    <p>Уважаемые пользователи! Операторы сотовой связи могут блокировать сообщения со слишком жестким контентом, направленным на запугивание покупателей и не имеющих никаких реальных основ.<br/>\n    Рекомендуем вам отправлять более лояльные тексты смс-сообщений или пользоваться функционалом робо-звонков. \n    Робот сможет звонить клиентам и диктовать текст любого содержания, а оплата будет производиться только в случае дозвона до покупателя.</p>\n</div>\n<div class=\"alert alert-info guide-text\">\n    В шаблоне текста SMS можно использовать следующие теги:\n    <ul>\n        <li><code>{{id}}</code> - возвращает номер заказа пользователя</li>\n        <li><code>{{status}}</code> - текущий статус заказа</li>\n        <li><code>{{date}}</code> - дата заказа в формате: 15.05.2019</li>\n        <li><code>{{time}}</code> - время заказа в формате: 17:47</li>\n        <li><code>{{datetime}}</code> - дата и время в формате: 2019-05-15 17:47:10</li>\n        <li><code>{{lastUpdate}}</code> - статус изменен в формате: 2019-05-15 17:47:10</li>\n        <li><code>{{lastModify}}</code> - последние изменение в формате: 2019-05-15 17:47:10</li>\n        <li><code>{{approvedAt}}</code> - дата и время апрува в формате: 2019-05-15 17:47:10, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{shippedAt}}</code> - дата и время отправки в формате: 2019-05-15 17:47:10, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{canceledAt}}</code> - дата и время отмены в формате: 2019-05-15 17:47:10, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{buyoutAt}}</code> - дата и время выкупа в формате: 2019-05-15 17:47:10, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{refundedAt}}</code> - дата и время возврата в формате: 2019-05-15 17:47:10, либо <code>NULL</code>, если не указана дата</li>\n        <li><code>{{price}}</code> - цена товара</li>\n        <li><code>{{total}}</code> - сумма заказа</li>\n        <li><code>{{goods_names}}</code> - наименование товаров через запятую</li>\n        <li><code>{{russianpostTrack}}</code> - номер отправления Почты России</li>\n        <li><code>{{russianpostTrackingIndex}}</code> - индекс почтового отделения последнего статуса отслеживания</li>\n        <li class=\"rp-tags\"><code>{{russianpostOfficeAddress}}</code> - адрес почтового отделения</li>\n        <li class=\"rp-tags\"><code>{{russianpostOfficePhone}}</code> - телефон почтового отделения</li>\n        <li class=\"rp-tags\"><code>{{russianpostWorkTimeToday}}</code> - режим работы почтового отделения сегодня</li>\n        <li class=\"rp-tags\"><code>{{russianpostWorkTimeTomorrow}}</code> - режим работы почтового отделения завтра</li>\n        <li><code>{{domain}}</code> - домен, на котором пользователь совершил заказ</li>\n        <li><code>{{utm_source}}</code> - метка utm_source</li>\n        <li><code>{{utm_medium}}</code> - метка utm_medium</li>\n        <li><code>{{utm_campaign}}</code> - метка utm_campaign</li>\n        <li><code>{{utm_content}}</code> - метка utm_content</li>\n        <li><code>{{utm_term}}</code> - метка utm_term</li>\n        <li><code>{{translit}}</code> - переводит сообщение на транслит (только для текстовых SMS)</li>\n        <li><code>{{fio}}</code> - возвращает значение поля «Ф.И.О». Аналогичным образом можно использовать поля:\n          	<code title=\"Индекс\">{{postIndex}}</code> \n          	<code title=\"Регион\">{{region}}</code> \n          	<code title=\"Город\">{{city}}</code> \n          	<code title=\"Адрес\">{{address}}</code> \n          	<code title=\"Телефон\">{{phone}}</code> \n          	<code title=\"Кол-во\">{{quantity}}</code> \n          	<code title=\"Комментарий\">{{comment}}</code> \n          	<code title=\"Liveinform\">{{additional1}}</code> \n          	<code title=\"Размер\">{{additional2}}</code> \n          	<code title=\"Дожим\">{{additional11}}</code> \n          	<code title=\"Масса\">{{additional14}}</code> \n      	</li>\n    </ul>\n</div>\n</div>\n',	'<div class=\"request\">\n    <span>{{{name}}}</span><span>{{{f1557932014n}}}</span><span>{{{f1557931993n}}}</span>\n    <details class=\"owner owner2\">\n        <summary class=\"tosetting\"></summary>\n        <div> <a crm=\"edit\" list=\"5\" class=\"add owner\">Редактировать</a>\n            <a crm=\"remove\" list=\"5\" class=\"delete owner\">В архив</a>\n        </div>\n    </details>\n</div>'),
(6,	'1v1-crm.ru',	6,	'История sms',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'',	'<div class=\"request\">\n    <span>Заказ: {{{in}}}</span><span>{{{out}}}</span><span>{{{datashow}}}</span><span>{{{name}}}</span>\n    <details class=\"owner owner2\">\n        <summary class=\"tosetting\"></summary>\n        <div><a crm=\"remove\" list=\"6\" class=\"delete owner\">В архив</a></div>\n    </details>\n</div>'),
(7,	'1v1-crm.ru',	7,	'История звонков',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'',	''),
(8,	'1v1-crm.ru',	8,	'Статусы',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'<div class=\"frm\">\r\n	<h3><span>Параметры статуса {{{name}}}</span></h3>\r\n    <div class=\"alert alert-danger\">При добавлении статуса обязательно присвойте его к группе статусов. Например, статус \"Перезвонить\" присвойте к группе статусов \"Обработка\".\r\n        <br/> Это очень важно, так как <b>от перемещения заказа между группами статусов зависит выплата вознаграждения веб-мастерам</b>\r\n    </div>\r\n    <span class=\"label\">Название<i required>*</i></span>{{{name.input[type:text,class:w500]}}}<br/>\r\n    <span class=\"label\">Группа<i required>*</i></span>{{{statusgroup.select[class:w300]}}}<br/>\r\n    <span class=\"label\">Сортировка<i required>*</i></span>{{{sortByLastStatusChange.select[class:w300]}}}<br/>\r\n    <span class=\"label\">Контейнер<i required>*</i></span>{{{container.select[class:w300]}}}<br/><br/>\r\n    <span class=\"label\"></span>{{{hideDataFromWebmaster.checkbox[label: Скрывать данные заказа от веб-мастера звездочками в этом статусе]}}}\r\n<div class=\"frmmar\"></div>\r\n	<h3>Перемещать заказ в другой статус по истечению заданного периода</h3>\r\n    <div class=\"alert alert-info\">Здесь вы можете задать время для нахождения заказа в этом статусе (<b>минимально 1 час</b>). Например, вы можете настроить автоматическое перемещение заказов из обработки в отмену в случае, если заказ в обработке находится более 14 дней. (Необходимо выставить 336 часов)\r\n        <br/>Установите количество часов в <b>0</b> чтобы отключить эту функцию\r\n    </div>\r\n  	Через {{{hoursToChange.input[type:text,class:w100]}}} ЧАСОВ изменить статус на {{{statusToChange.select[class:w300]}}}\r\n<div class=\"frmmar\"></div>\r\n	<h3>Автоматически отправлять SMS при попадании заказа в этот статус</h3>\r\n	<div class=\"alert alert-info\">Вы можете задать смс-шаблон, который будет автоматически отправляться на номер телефона вашего клиента при попадании заказа в этот статус.</div>\r\n    <span class=\"label\"></span>{{{alwaysSendAutoSms.checkbox[label: Всегда отсылать авто SMS]}}}<br/>\r\n    <span class=\"label\">Автоматически отправлять текстовое SMS при попадании заказа в этот статус<i required>*</i></span>{{{smsTemplateID.select[class:w300]}}}<br/>\r\n    <span class=\"label\">Автоматически отправлять голосовое SMS при попадании заказа в этот статус<i required>*</i></span>{{{voiceSmsTemplateID.select[class:w300]}}}\r\n<div class=\"frmmar\"></div>\r\n	<h3>Перемещать заказ в другой статус по статусу почты России</h3>\r\n<div class=\"alert alert-info\">Здесь вы можете задать ключевое слово, по которому заказ будет перемещаться в выбранный статус.<br/>\r\n	<div class=\"spoiler\">\r\n	    <div class=\"spoiler-btn\">Ключевые слова Почты России</div>\r\n	    <div class=\"spoiler-body collapse in\" style=\"height: auto;\" aria-expanded=\"true\">\r\n	        <ul>\r\n	            <li>\r\n	                <b>Прибыло в место вручения</b>\r\n	                <ul>\r\n	   <li>Хранение - До востребования</li>\r\n		<li>Хранение - На абонементный ящик</li>\r\n		<li>Хранение - Установленный срок хранения</li>\r\n		<li>Хранение - Продление срока хранения по заявлению адресата</li>\r\n		<li>Прибыло в место вручения</li>\r\n		<li>Прибыло в почтомат</li>\r\n		<li>Передано курьеру</li>\r\n		<li>Доставлено для вручения электронно</li>\r\n		<li>Передано почтальону</li>\r\n		<li>Ожидает курьерской доставки</li>\r\n		<li>Продление срока хранения</li>\r\n		<li>Направлено извещение</li>\r\n		<li>Доставлено извещение</li>\r\n		<li>Временное отсутствие адресата</li>\r\n		<li>Доставка отложена по просьбе адресата</li>\r\n	                </ul>\r\n	            </li>\r\n	            <li>\r\n	                <b>Вручение</b>\r\n	                <ul>\r\n		<li>Вручение адресату</li>\r\n		<li>Выдано адресату через почтомат</li>\r\n		<li>Адресату электронно</li>\r\n		<li>Адресату почтальоном</li>\r\n		<li>Адресату курьером</li>\r\n		<li>Адресату с контролем ответа</li>\r\n		<li>Адресату с контролем ответа почтальоном</li>\r\n		<li>Адресату с контролем ответа курьером</li>\r\n		<li>Доставлено в почтовый ящик</li>\r\n		<li>Доставлено в руки адресату под роспись</li>\r\n		<li>Доставлено на ресепшн или секретариат под роспись</li>\r\n	                </ul>\r\n	            </li>\r\n	            <li>\r\n	                <b>Возврат</b>\r\n	                <ul>\r\n		<li>Вручение отправителю</li>\r\n		<li>Истек срок хранения</li>\r\n		<li>Заявление отправителя</li>\r\n		<li>Отсутствие адресата по указанному адресу</li>\r\n		<li>Отказ адресата</li>\r\n		<li>Смерть адресата</li>\r\n		<li>Невозможно прочесть адрес адресата</li>\r\n		<li>Отказ в выпуске таможней</li>\r\n		<li>Адресат, абонирующий абонементный почтовый шкаф, не указан или указан неправильно</li>\r\n		<li>Иные обстоятельства</li>\r\n		<li>Неверный адрес</li>\r\n		<li>Несоответствие комплектности</li>\r\n		<li>Запрещено САБ</li>\r\n		<li>Передача в невостребованные</li>\r\n		<li>Утрачено</li>\r\n		<li>Нероздано</li>\r\n		<li>Невостребовано</li>\r\n		<li>Содержимое запрещено к пересылке</li>\r\n		<li>Ожидает результаты экспертизы</li>\r\n		<li>Адресат выбыл</li>\r\n		<li>Отказ от получения</li>\r\n		<li>Истек срок хранения в почтомате</li>\r\n		<li>Отказ в получении</li>\r\n		<li>Адресат выбыл</li>\r\n	                </ul>\r\n	            </li>\r\n	        </ul>\r\n	    </div>\r\n	</div>\r\n</div>\r\n	Если {{{ifRpStatus1.select[class:w300]}}} то изменить статус на {{{thenRpStatus1.select[class:w300]}}}<br/>\r\n	Если {{{ifRpStatus2.select[class:w300]}}} то изменить статус на {{{thenRpStatus2.select[class:w300]}}}<br/>\r\n	Если {{{ifRpStatus3.select[class:w300]}}} то изменить статус на {{{thenRpStatus3.select[class:w300]}}}<br/>\r\n	Если {{{ifRpStatus4.select[class:w300]}}} то изменить статус на {{{thenRpStatus4.select[class:w300]}}}\r\n<div class=\"frmmar\"></div>\r\n	<h3>Действия со складом</h3>\r\n	<div class=\"alert alert-info\">Здесь вы задаете параметры, которые управляют остатками на складе.\r\n		<ul>\r\n			<li>Зарезервировать - вычесть товар из остатков на складе. Обычно используется для статусов «Принят», «Отправлен», «Оплачен»</li>\r\n			<li>Обнулить - вернуть товар обратно на склад, в случае, если он был зарезервирован</li>\r\n		</ul>\r\n	</div>\r\n    <span class=\"label\">Действия с количеством товара</span>{{{goodsQuantity.select[class:w300]}}}\r\n<div class=\"frmmar\"></div>\r\n	<h3>Режим прозвона</h3>\r\n	<div class=\"alert alert-info\">Автоматически добавлять заказы в режим прозвона</div>\r\n    <span class=\"label\">Режим прозвона</span>{{{callmodeGroup.select[class:w300]}}}\r\n<div class=\"frmmar\"></div>\r\n	<button class=\"save\" action=\"addf\">Продолжить</button>\r\n	<span class=\"closeform\">Отмена</span>\r\n</div>\r\n',	'<div class=\"request\">\n    <span>({{{ids}}}) {{{name}}}</span><span>{{{statusgroup}}}</span>\n    <details class=\"owner owner2\">\n        <summary class=\"tosetting\"></summary>\n        <div> <a crm=\"edit\" list=\"8\" class=\"add owner\">Редактировать</a>\n            <a crm=\"remove\" list=\"8\" class=\"delete owner\">В архив</a>\n        </div>\n    </details>\n</div>'),
(9,	'1v1-crm.ru',	9,	'Контейнеры статусов',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'\r\n',	'',	'',	'',	'<div class=\"frm\">\n	<h3><span>Параметры контейнера {{{ids}}}</span></h3>\n    <span class=\"label\">Название<i required>*</i></span>{{{name.input[type:text,class:w500]}}}<br/>\n<div class=\"frmmar\"></div>\n	<button class=\"save\" action=\"addf\">Продолжить</button>\n	<span class=\"closeform\">Отмена</span>\n</div>\n',	'<div class=\"request\">\r\n    <span>{{{name}}}</span><span></span>\r\n    <details class=\"owner owner2\">\r\n        <summary class=\"tosetting\"></summary>\r\n        <div> <a crm=\"edit\" list=\"9\" class=\"add owner\">Редактировать</a>\r\n            <a crm=\"remove\" list=\"9\" class=\"delete owner\">В архив</a>\r\n        </div>\r\n    </details>\r\n</div>'),
