(11,	'1v1-crm.ru',	11,	'Модуль Онлайн-сервиса Отправка',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'<div class=\"frm\">\r\n	<h3><span>Шаблон онлайн-сервиса Отправка {{{ids}}}</span></h3>\r\n    <span class=\"label\">Аккаунт</span>{{{account.select[class:w500]}}}<br/>\r\n    <span class=\"label\">Название шаблона</span>{{{accountTemplateName.input[type:text,class:w500,placeholder:Не указано]}}}<br/>\r\n    <span class=\"label\">Тип бланка</span>{{{accountTemplate.select}}}\r\n<div class=\"frmmar\"></div>\r\n	<h3>Форма 7</h3>\r\n    <span class=\"label\">Отправитель на посылке/название бренда</span>{{{name.input[type:text,class:w500,placeholder:Не указано]}}}<br/>\r\n    <span class=\"label\">Адрес отправителя</span>{{{senderAddress.input[type:text,class:w500,placeholder:Не указано]}}}<br/>\r\n<div class=\"columncount2\">\r\n    <span class=\"label\">Код страны</span>{{{sender_country.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n    <span class=\"label\">Индекс места приема</span>{{{sender_postOfficeIndex.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n    <span class=\"label\">Размеры: высота</span>{{{dimension_height.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n    <span class=\"label\">Размеры: длина</span>{{{dimension_length.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n    <span class=\"label\">Размеры: ширина</span>{{{dimension_width.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n    <span class=\"label\">Фиксированная объявленная ценность</span>{{{declaredValueFix.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n    <span class=\"label\">Категория почтового отправления</span>{{{sender_mailCtg.select}}}<br/>\r\n    <span class=\"label\">Тип адреса</span>{{{to_typeAddress.select}}}<br/>\r\n    <span class=\"label\">Дата сдачи в почтовое отделение</span>{{{system_dateDelivery.select}}}<br/>\r\n    <span class=\"label\">Получать тариф в доп. поле</span>{{{getTariff.select}}}<br/>\r\n    <span class=\"label\">Вес товара вручную в граммах </span>{{{weight_custom.select}}}<br/>\r\n    <span class=\"label\">Cтатус, в который переместится заказ после экспорта</span>{{{status_exported.select}}}\r\n</div>\r\n<div class=\"frmmar\"></div>\r\n    <span class=\"label\"></span>{{{isCourier.checkbox[label: Отметка «Курьер»]}}}<br/>\r\n    <span class=\"label\"></span>{{{isFragile.checkbox[label: Отметка «Осторожно/Хрупкое»]}}}<br/>\r\n    <span class=\"label\"></span>{{{isNoReturn.checkbox[label: Отметка «Возврату не подлежит»]}}}<br/>\r\n    <span class=\"label\"></span>{{{isOrderNotice.checkbox[label: Отметка «С заказным уведомлением»]}}}<br/>\r\n    <span class=\"label\"></span>{{{isSimpleNotice.checkbox[label: Отметка «С простым уведомлением»]}}}<br/>\r\n    <span class=\"label\"></span>{{{notice_sms.checkbox[label: Признак услуги SMS уведомления]}}}<br/>\r\n    <span class=\"label\"></span>{{{weight.checkbox[label: Выводить вес со склада и считать тариф]}}}<br/>\r\n	<span class=\"label\"></span>{{{datamatrix_use.checkbox[label: Печатать двумерный матричный код]}}}\r\n<div class=\"frmmar\"></div>\r\n	<h3>Форма 112</h3>\r\n  	<span class=\"label\">Получатель перевода</span>{{{datamatrix_sender.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Адрес получателя перевода</span>{{{receiver_to.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Регион получателя перевода</span>{{{datamatrix_region.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Зона информации клиента</span>{{{fk_infozone.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Номер телефона получателя перевода</span>{{{receiver_phone.input[type:text,class:w200,placeholder:+7]}}}<br/>\r\n	<span class=\"label\">Код федерального клиента</span>{{{fk_code.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Почтовый индекс получателя перевода</span>{{{datamatrix_postIdnex.input[type:text,class:500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Тип получателя перевода и форма оплаты</span>{{{datamatrix_payType.select[class:w500]}}}<br/>\r\n	<span class=\"label\">Тип отправителя перевода</span>{{{datamatrix_senderPayType.select[class:w500]}}}<br/>\r\n	<span class=\"label\">ИНН получателя</span>{{{datamatrix_inn.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">БИК банка получателя</span>{{{datamatrix_bik.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Расчетный счет получателя</span>{{{datamatrix_raschet.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Корреспондентский счет банка получателя</span>{{{datamatrix_korRaschet.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Наименование банка получателя</span>{{{datamatrix_bankName.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">ШПИ РПО с наложенным платежом</span>{{{datamatrix_cod.select[class:w500]}}}\r\n<div class=\"frmmar\"></div>\r\n	<button class=\"save\" action=\"addf\">Продолжить</button>\r\n	<span class=\"closeform\">Отмена</span>\r\n</div>\r\n',	'<div class=\"request\">\n    <span>{{{accountTemplateName}}}</span><span>{{{account}}}</span><span></span>\n    <details class=\"owner owner2\">\n        <summary class=\"tosetting\"></summary>\n        <div> <a crm=\"edit\" list=\"11\" class=\"add owner\">Редактировать</a>\n            <a crm=\"remove\" list=\"11\" class=\"delete owner\">В архив</a>\n        </div>\n    </details>\n</div>'),
