bel\">Телефон</span>{{{phone.input[type:text,placeholder:0]}}}\n				<span class=\"label\">ФИО<i required>*</i></span><span style=\"position:relative\">{{{name.input[type:text,placeholder:Не указано]}}}</span>\n				<span class=\"label\">Адрес</span>{{{address.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Город</span>{{{city.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Размер</span>{{{size.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Почта России: Track</span>{{{russianpostTrack.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Комментарий</span>{{{comment.textarea}}}\n				<span class=\"label\">Доп.поле 1</span>{{{dop1.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Доп.поле 2</span>{{{dop2.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Доп.поле 3</span>{{{dop3.input[type:text,placeholder:0]}}}\n    			<span class=\"label\">Доп.поле 4</span>{{{dop4.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Доп.поле 5</span>{{{dop5.input[type:text,placeholder:0]}}}\n			</div>\n    		<div class=\"col\">\n				<span class=\"label\">Индекс</span>{{{postIndex.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Регион</span>{{{region.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Квартира</span>{{{flat.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Дом</span>{{{house.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Liveinform ID</span>{{{liveinformId.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Масса</span>{{{weight.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Дожим</span>{{{completely.textarea}}}\n				<span class=\"label\">Доп.поле 6</span>{{{dop6.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Доп.поле 7</span>{{{dop7.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Доп.поле 8</span>{{{dop8.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Доп.поле 9</span>{{{dop9.input[type:text,placeholder:0]}}}\n				<span class=\"label\">Доп.поле 10</span>{{{dop10.input[type:text,placeholder:0]}}}\n				<span class=\"label\">{{{goods_names.input[type:text,class:none]}}}</span>\n				<span class=\"label\">{{{total.input[type:text,class:none]}}}</span>\n				<span class=\"label\">{{{all.input[type:text,class:none]}}}</span>\n				<span class=\"label\">{{{operator.input[type:text,class:none]}}}</span>\n				<span class=\"label\">{{{robot.input[type:text,class:none]}}}</span>\n				<span class=\"label\">{{{currentSms.input[type:text,class:none]}}}</span>\n			</div>\n		</div>\n	</div>	\n	<div class=\"col\">\n		{{{dataCheck}}}\n		<span class=\"label\">Статус<i required>*</i></span>{{{status.select}}}\n		{{{operators}}}{{{sendSms}}}{{{addMarket}}}\n      \n      <div class=\"log_robot\">\n		<input type=\"checkbox\" name=\"vkl\" id=\"vkl3\" />\n		<label for=\"vkl3\">Лог робота</label>\n		<div>{{{log_robot.textarea[placeholder:Лог робота]}}}</div>\n	</div>\n      	<div class=\"legend\"><li><span>Домен: </span><a>{{{domain2.link[target:_blank,rel:noopener noreferrer]}}}</a></li></div>\n	</div>\n  	<script>setTimeout(() => {\n		renderer.suggest(\"#address\", \"address\");\n		renderer.suggest(\".name\", \"name\");\n	}, 2000)</script>\n</div>\n',	'<tr class=\"request\">\n  	<td><a crm=\"edit\" list=\"20\" class=\"add\" title=\"Редактировать\"></a>{{{historyLink}}}</td>\n   	<td label=\"ids\"><span>{{{ids}}}</span></td>\n	<td label=\"operator\"><span>{{{operatorName}}}</span></td>\n	<td label=\"goods_names\"><span>{{{goods_names}}}</span></td>\n	<td label=\"comment\"><span>{{{comment}}}</span></td>\n	<td label=\"russianpostTrack\"><span>{{{russianpostTrack}}}</span></td>\n	<td label=\"russianpostStatus\"><div>{{{russianpostStatus.details}}}</div></td>\n	<td label=\"name\"><span>{{{name}}}</span></td>\n	<td label=\"statustime\"><span>{{{statustime.time}}}</span></td>\n	<td label=\"lastUpdate\"><span>{{{lastUpdate.time}}}</span></td>\n	<td label=\"time_call\"><span>{{{time_call.time}}}</span></td>\n	<td label=\"timeClient\"><span>{{{timeClient}}}</span></td>\n	<td label=\"postIndex\"><span>{{{postIndex}}}</span></td>\n	<td label=\"region\"><span>{{{region}}}</span></td>\n	<td label=\"city\"><span>{{{city}}}</span></td>\n	<td label=\"address\"><span>{{{address}}}</span></td>\n	<td label=\"house\"><span>{{{house}}}</span></td>\n	<td label=\"flat\"><span>{{{flat}}}</span></td>\n	<td label=\"count\"><span>{{{count}}}</span></td>\n	<td label=\"all\"><div>{{{getDouble}}}</div></td>\n	<td label=\"total\"><span>{{{total}}}</span></td>\n	<td label=\"lastSms\"><div>{{{lastSms.details}}}</div></td>\n	<td label=\"smsStatus\"><span>{{{smsStatus}}}</span></td>\n	<td label=\"lastVoiceSms\"><span>{{{lastVoiceSms}}}</span></td>\n	<td label=\"lastVoiceStatus\"><span>{{{lastVoiceStatus}}}</span></td>\n	<td label=\"liveinformId\"><span>{{{liveinformId}}}</span></td>\n	<td label=\"liveinform\"><span>{{{liveinform}}}</span></td>\n	<td label=\"size\"><span>{{{size}}}</span></td>\n	<td label=\"completely\"><span>{{{completely}}}</span></td>\n	<td label=\"weight\"><span>{{{weight}}}</span></td>\n	<td label=\"tag\"><span>{{{tag}}}</span></td>\n	<td label=\"source\"><span>{{{source}}}</span></td>\n	<td label=\"ip\"><span>{{{ip}}}</span></td>\n	<td label=\"referrer\"><div>{{{referrer.details}}}</div></td>\n	<td label=\"dop1\"><span>{{{dop1}}}</span></td>\n	<td label=\"dop2\"><span>{{{dop2}}}</span></td>\n	<td label=\"dop3\"><span>{{{dop3}}}</span></td>\n	<td label=\"dop4\"><span>{{{dop4}}}</span></td>\n	<td label=\"dop5\"><span>{{{dop5}}}</span></td>\n	<td label=\"dop6\"><span>{{{dop6}}}</span></td>\n	<td label=\"dop7\"><span>{{{dop7}}}</span></td>\n	<td label=\"dop8\"><span>{{{dop8}}}</span></td>\n	<td label=\"dop9\"><span>{{{dop9}}}</span></td>\n	<td label=\"dop10\"><span>{{{dop10}}}</span></td>\n	<td label=\"domain2\"><span>{{{domain2}}}</span></td>\n	<td label=\"timezone\"><span>{{{timezone}}}</span></td>\n	<td label=\"approvedAt\"><span>{{{approvedAt.time}}}</span></td>\n	<td label=\"shippedAt\"><span>{{{shippedAt.time}}}</span></td>\n	<td label=\"canceledAt\"><span>{{{canceledAt.time}}}</span></td>\n	<td label=\"buyoutAt\"><span>{{{buyoutAt.time}}}</span></td>\n	<td label=\"refundedAt\"><span>{{{refundedAt.time}}}</span></td>\n	<td label=\"log_robot\"><div>{{{log_robot.details}}}</div></td>\n</tr>'),
(21,	'1v1-crm.ru',	21,	'Категории товаров',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'<div class=\"frm\">\r\n	<h3>Параметры категории</h3>\r\n    <span class=\"label\">Название<i required>*</i></span>{{{name.input[type:text,class:w500]}}}<br/>\r\n<div class=\"frmmar\"></div>\r\n	<button class=\"save\" action=\"addf\">Продолжить</button>\r\n	<span class=\"closeform\">Отмена</span>\r\n</div>\r\n',	'<div class=\"request\">\r\n    <span>{{{name}}}</span><span></span>\r\n    <details class=\"owner owner2\">\r\n        <summary class=\"tosetting\"></summary>\r\n        <div> <a crm=\"edit\" list=\"21\" class=\"add owner\">Редактировать</a>\r\n            <a crm=\"remove\" list=\"21\" class=\"delete owner\">В архив</a>\r\n        </div>\r\n    </details>\r\n</div>'),
(22,	'1v1-crm.ru',	22,	'Товары',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'<div class=\"frm\">\r\n	<h3><span>Товар {{{ids}}}</span></h3>\r\n    <span class=\"label\">Название<i required>*</i></span>{{{name.input[type:text,class:w500,placeholder:Название]}}}<br/>\r\n	<span class=\"label\">Категория</span>{{{category.select[class:w500,placeholder:0]}}}<br/><br/>\r\n 	<div class=\"alert alert-info\" style=\"margin-bottom: 10px;\">Поле алиас необходимо для корректной работы лендингов. Алиас может состоять только из букв латинского алфавита, цифр и символов «-», «_».</div>\r\n     <span class=\"label\">Алиас</span>{{{alias.input[type:text,class:w500,placeholder:Алиас]}}}<br/>\r\n    <span class=\"label\">Описание</span>{{{description.textarea}}}<br/>\r\n<div class=\"frmmar\"></div>\r\n	<h3>Дополнительно</h3>\r\n	<span class=\"label\">Единица измерения</span>{{{unity.input[type:text,class:w100,placeholder:шт]}}}<br/>\r\n	<span class=\"label\">Вес в граммах</span>{{{weight.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Длина (см)</span>{{{length.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Ширина (см)</span>{{{width.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Высота (см)</span>{{{height.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Закупочная цена</span>{{{price.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n	<span class=\"label\">На складе</span>{{{countAll.input[type:text,class:w100,placeholder:0]}}}<br/><br/>\r\n	<span class=\"label\"></span>{{{parse.checkbox[label: Вести учет остатков этого товара?]}}}<br/>\r\n<div class=\"frmmar\"></div>\r\n	<h3>Цены</h3>\r\n  	{{{priceAll.some}}}\r\n<div class=\"frmmar\"></div>\r\n	<button class=\"save\" action=\"addf\">Продолжить</button>\r\n	<span class=\"closeform\">Отмена</span>\r\n</div>\r\n',	'<div class=\"request\">\n    <span class=\"ids_first\">{{{ids}}}</span><span>{{{name}}}</span><span>{{{price}}} руб.</span><span>{{{category}}}</span><span>{{{countAll}}} шт.</span>\n    <details class=\"owner owner2\">\n        <summary class=\"tosetting\"></summary>\n        <div> <a crm=\"edit\" list=\"22\" class=\"add owner\">Редактировать</a>\n            <a crm=\"remove\" list=\"22\" class=\"delete owner\">В архив</a>\n        </div>\n    </details>\n</div>'),
