(24,	'1v1-crm.ru',	24,	'Почта России Форма 7А',	'0_0_0',	'',	'content2',	1,	5,	'',	'',	50,	'',	'',	'',	'',	'',	'',	'',	'',	'<div class=\"frm\">\r\n	<h3><span>Форма 7а (ярлык 1 кл) {{{ids}}}</span></h3>\r\n  	<span class=\"label\">Текст «От кого»</span>{{{from_name.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Текст «Откуда»</span>{{{from_city.input[type:text,class:w500,placeholder:0]}}}<br/>\r\n	<span class=\"label\">Текст «Индекс места отправления»</span>{{{from_postIndex.input[type:text,class:w100,placeholder:0]}}}<br/>\r\n	<span class=\"label\"></span>{{{type_letter.checkbox[label: Письмо 1-го класса]}}}<br/>\r\n	<span class=\"label\"></span>{{{type_banderol.checkbox[label: Бандероль 1-го класса]}}}<br/>\r\n	<span class=\"label\"></span>{{{type_posylka.checkbox[label: Посылка 1-го класса]}}}<br/>\r\n	<span class=\"label\"></span>{{{type_ob.checkbox[label: С объявленной ценностью]}}}<br/>\r\n	<span class=\"label\"></span>{{{type_naloj.checkbox[label: С наложенным платежом]}}}<br/>\r\n	<span class=\"label\"></span>{{{type_opis.checkbox[label: С описью]}}}<br/>\r\n	<span class=\"label\"></span>{{{type_simplenotice.checkbox[label: С простым уведомлением]}}}<br/>\r\n	<span class=\"label\"></span>{{{type_zakaznotice.checkbox[label: С заказным уведомлением]}}}<br/>\r\n	<span class=\"label\"></span>{{{type_naloj_inside.checkbox[label: Наложенный платеж внутри]}}}<br/>\r\n	<span class=\"label\"></span>{{{kpsh_print.checkbox[label: Печатать КПШ]}}}<br/>\r\n	<span class=\"label\"></span>{{{notice_phone.checkbox[label: Выводить номер телефона отправителя]}}}<br/>\r\n	<span class=\"label\"></span>{{{notice_phoneReciever.ccheckboxheck[label: Выводить номер телефона получателя]}}}<br/>\r\n	<span class=\"label\"></span>{{{weight.checkbox[label: Выводить вес со склада и считать тариф]}}}<br/>\r\n	<span class=\"label\"></span>{{{air_notice_returnAddress.checkbox[label: Вернуть по обратному адресу]}}}<br/>\r\n	<span class=\"label\"></span>{{{air_notice